import torch
import torch.nn as nn
import triton
import triton.language as tl


@triton.autotune(
    configs=[
        triton.Config({"BLOCK_SIZE": 1024 * 16}, num_warps=32, num_stages=2),
        triton.Config({"BLOCK_SIZE": 1024 * 8}, num_warps=16, num_stages=2),
        triton.Config({"BLOCK_SIZE": 1024 * 4}, num_warps=8, num_stages=2),
        triton.Config({"BLOCK_SIZE": 1024 * 2}, num_warps=4, num_stages=2),
    ],
    key=["n_elements"],
)
@triton.jit
def scalar_mul_kernel(
    input_ptr,
    output_ptr,
    scalar,
    n_elements,
    BLOCK_SIZE: tl.constexpr,
):
    pid = tl.program_id(0)
    offsets = pid * BLOCK_SIZE + tl.arange(0, BLOCK_SIZE)
    mask = offsets < n_elements
    x = tl.load(input_ptr + offsets, mask=mask)
    result = x * scalar
    tl.store(output_ptr + offsets, result.to(tl.bfloat16), mask=mask)


class Model(nn.Module):
    def __init__(self):
        super(Model, self).__init__()

    def forward(self, A: torch.Tensor, s) -> torch.Tensor:
        A = A.contiguous()
        output = torch.empty_like(A)
        n_elements = A.numel()
        if isinstance(s, torch.Tensor):
            scalar_val = s.item()
        else:
            scalar_val = float(s)
        grid = lambda META: (triton.cdiv(n_elements, META["BLOCK_SIZE"]),)
        scalar_mul_kernel[grid](A, output, scalar_val, n_elements)
        return output
